SELECT r.*,rs.runtime_state,rs.state_revision AS runtime_revision
FROM rag_incremental_runs r JOIN rag_runtime_state rs ON rs.collection_name=r.collection_name
WHERE r.incremental_run_id='{{ $items("Normalize Coordinator Command")[0].json.incremental_run_id }}';
